solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

std::optional<std::vector<std::uint8_t>> encodeName(const std::string& name)
{
    std::string n{ name };
    if (!n.empty() && n.back() == '.') n.pop_back();
    std::vector<std::uint8_t> out;
    if (!n.empty())
    {
        std::size_t start{ 0 };
        while (true)
        {
            const std::size_t dot{ n.find('.', start) };
            const std::string label{ n.substr(start, dot == std::string::npos ? std::string::npos : dot - start) };
            if (label.empty() || label.size() > 63) return std::nullopt;
            out.push_back(static_cast<std::uint8_t>(label.size()));
            out.insert(out.end(), label.begin(), label.end());
            if (dot == std::string::npos) break;
            start = dot + 1;
        }
    }
    out.push_back(0);
    if (out.size() > 255) return std::nullopt;
    return out;
}

std::optional<std::string> decodeName(const std::vector<std::uint8_t>& packet, std::size_t& at)
{
    std::string name;
    std::size_t pos{ at };
    bool jumped{ false };
    int jumps{ 0 };
    while (true)
    {
        if (pos >= packet.size()) return std::nullopt;
        const std::uint8_t length{ packet[pos] };
        if ((length & 0xC0) == 0xC0)
        {
            if (pos + 1 >= packet.size() || ++jumps > 20) return std::nullopt;
            const std::size_t target{ static_cast<std::size_t>(((length & 0x3F) << 8) | packet[pos + 1]) };
            if (!jumped) { at = pos + 2; jumped = true; }
            pos = target;
            continue;
        }
        if (length & 0xC0) return std::nullopt;
        if (length == 0)
        {
            if (!jumped) at = pos + 1;
            return name.empty() ? std::string(".") : name;
        }
        if (pos + 1 + length > packet.size()) return std::nullopt;
        if (!name.empty()) name += '.';
        name.append(packet.begin() + static_cast<std::ptrdiff_t>(pos + 1), packet.begin() + static_cast<std::ptrdiff_t>(pos + 1 + length));
        pos += 1 + length;
    }
}

std::vector<std::uint8_t> buildQuery(std::uint16_t id, const std::string& name, std::uint16_t type)
{
    const auto encoded{ encodeName(name) };
    if (!encoded) return {};
    std::vector<std::uint8_t> q{ static_cast<std::uint8_t>(id >> 8), static_cast<std::uint8_t>(id), 0x01, 0x00, 0, 1, 0, 0, 0, 0, 0, 0 };
    q.insert(q.end(), encoded->begin(), encoded->end());
    q.push_back(static_cast<std::uint8_t>(type >> 8));
    q.push_back(static_cast<std::uint8_t>(type));
    q.push_back(0);
    q.push_back(1);
    return q;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
TEST("encoding names") {
    CHECK(encodeName("a.bc") == std::optional<Bytes>{ Bytes{ 1, 'a', 2, 'b', 'c', 0 } });
    CHECK(encodeName("example.com.") == encodeName("example.com"));
    CHECK(encodeName(".") == std::optional<Bytes>{ Bytes{ 0 } });
    CHECK(encodeName("") == std::optional<Bytes>{ Bytes{ 0 } });
    CHECK(!encodeName("a..b").has_value());
    CHECK(!encodeName(std::string(64, 'x') + ".com").has_value());
    std::string longName;
    for (int i{ 0 }; i < 5; ++i) longName += std::string(60, 'a') + ".";
    CHECK(!encodeName(longName).has_value());
}
TEST("decoding plain names") {
    const Bytes p{ 9, 9, 5, 'x', 'e', 'n', 'o', 'n', 3, 'd', 'e', 'v', 0, 7 };
    std::size_t at{ 2 };
    CHECK_EQ(decodeName(p, at).value_or("?"), std::string("xenon.dev"));
    CHECK_EQ(at, 13u);
    std::size_t root{ 0 };
    CHECK_EQ(decodeName(Bytes{ 0 }, root).value_or("?"), std::string("."));
}
TEST("compression pointers") {
    Bytes p(12, 0);
    const auto first{ *encodeName("justloofy.dev") };
    p.insert(p.end(), first.begin(), first.end());
    const std::size_t second{ p.size() };
    for (std::uint8_t b : Bytes{ 5, 'x', 'e', 'n', 'o', 'n', 0xC0, 12 }) p.push_back(b);
    p.push_back(0xAA);
    std::size_t at{ second };
    CHECK_EQ(decodeName(p, at).value_or("?"), std::string("xenon.justloofy.dev"));
    CHECK_EQ(at, second + 8);
    std::size_t direct{ p.size() };
    p.push_back(0xC0); p.push_back(static_cast<std::uint8_t>(second));
    CHECK_EQ(decodeName(p, direct).value_or("?"), std::string("xenon.justloofy.dev"));
}
TEST("hostile names") {
    const Bytes loop{ 0xC0, 0x00 };
    std::size_t at{ 0 };
    CHECK(!decodeName(loop, at).has_value());
    std::size_t at2{ 0 };
    CHECK(!decodeName(Bytes{ 5, 'a', 'b' }, at2).has_value());
    std::size_t at3{ 0 };
    CHECK(!decodeName(Bytes{ 0x40, 'a', 0 }, at3).has_value());
    std::size_t at4{ 0 };
    CHECK(!decodeName(Bytes{ 0xC0 }, at4).has_value());
}
TEST("a query") {
    const Bytes q{ buildQuery(0xBEEF, "a.bc", 28) };
    CHECK(q == (Bytes{ 0xBE, 0xEF, 0x01, 0x00, 0, 1, 0, 0, 0, 0, 0, 0, 1, 'a', 2, 'b', 'c', 0, 0, 28, 0, 1 }));
    CHECK(buildQuery(1, "a..b", 1).empty());
}

